"""Extract real shader macro/call sites, texture submission and Host readers.

Uses the production IPC fixture, not a substitute serializer. Wrappers test only
the submission scope: D3D validation, stateblocks and COM lifetimes stay outside
this regression. NULL inputs deliberately exercise the transport contract only.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re

from generate_buffer_contract_test import method
from generate_ipc_transport_test import generate as generate_transport

ROOT = Path(__file__).resolve().parents[1]
SHADERS = tuple('Set' + shader + 'ShaderConstant' + kind
                for shader in ('Vertex', 'Pixel') for kind in ('F', 'I', 'B'))


def digest(text):
    return hashlib.sha256(text.encode('utf-8')).hexdigest()


def macro(text, name):
    lines = text.splitlines()
    starts = [i for i, line in enumerate(lines) if line.startswith('#define ' + name + '(')]
    if len(starts) != 1:
        raise ValueError('Expected one original macro: ' + name)
    end = starts[0]
    while lines[end].endswith('\\'):
        end += 1
    return '\n'.join(lines[starts[0]:end + 1])


def generate(source, output):
    generate_transport(source, output)
    client = (source / 'bridge/src/client/d3d9_device.cpp').read_text(encoding='utf-8')
    host = (source / 'bridge/src/server/main.cpp').read_text(encoding='utf-8')
    shader_macro = macro(client, 'SetShaderConst')
    if 'bridge_data::payload(' not in shader_macro or 'c.send_' in shader_macro:
        raise ValueError('Shader macro must use complete Packet payload')
    wrappers = ['#include <d3d9.h>', 'using Device = Bridge<BridgeId::Device>;',
                '#ifdef REMIX_BRIDGE_CLIENT', 'using ClientMessage = Device::Command;',
                shader_macro, 'struct ShaderTextureSender {',
                'uint32_t getId() const { return 0xc0dec0deu; }']
    readers, metadata = [], {'SetShaderConst': {'macro_sha256': digest(shader_macro)}}
    for name in SHADERS:
        marker = 'HRESULT Direct3DDevice9Ex_LSS<EnableSync>::' + name + '('
        start, end = method(client, marker)
        body = client[start:end]
        signature = re.match(re.escape(marker) + r'([^)]*)\)', body).group(1)
        calls = re.findall(r'SetShaderConst\(' + name + r',[^;]+;', body)
        if len(calls) != 1:
            raise ValueError(name + ': expected exactly one original macro invocation')
        invocation = calls[0]
        wrappers += ['UID ' + name + '(' + signature + ') {', 'UID currentUID = 0;',
                     invocation, 'return currentUID;', '}']
        hs, he = method(host, 'case IDirect3DDevice9Ex_' + name + ':')
        host_case = host[hs:he]
        matches = re.findall(r'PULL_U\(StartRegister\);\s*PULL_U\(Count\);\s*'
                             r'(?:float|int|BOOL)\* pConstantData = nullptr;\s*'
                             r'PULL_DATA\([^;]+;', host_case)
        if len(matches) != 1:
            raise ValueError(name + ': unexpected original Host reader')
        reader = matches[0]
        readers += ['HostPayload read_' + name + '() {', reader,
                    'return {StartRegister, Count, pConstantData_len, pConstantData};', '}']
        metadata[name] = {'signature': signature, 'client_invocation_sha256': digest(invocation),
                          'host_reader_sha256': digest(reader)}
    start, end = method(client, 'HRESULT Direct3DDevice9Ex_LSS<EnableSync>::SetTexture(')
    body = client[start:end]
    opcode = 'Commands::IDirect3DDevice9Ex_SetTexture'
    if body.count('ClientMessage c(' + opcode + ',') != 1:
        raise ValueError('SetTexture: expected exactly one submission')
    command = body.index('ClientMessage c(' + opcode + ',')
    opening = body.rfind('{', 0, command)
    scope = body[opening:body.index('}', command) + 1]
    if not re.fullmatch(r'\{\s*ClientMessage c\([^;]+;\s*currentUID = c.get_uid\(\);\s*\}', scope):
        raise ValueError('SetTexture: unexpected submission scope; review extraction')
    if 'bridge_data::fields(' not in scope:
        raise ValueError('SetTexture must use complete Packet fields')
    # uintptr_t is a transport-only handle stand-in, never a fake COM object.
    wrappers += ['UID SetTexture(DWORD Stage, uintptr_t pD3DObject) {', 'UID currentUID = 0;',
                 scope, 'return currentUID;', '}', '};', '#undef SetShaderConst', '#else',
                 'using DeviceBridge = Device;',
                 'struct HostPayload { uint32_t start, count, bytes; const void* data; };']
    for name in ('PULL', 'PULL_U', 'PULL_D', 'PULL_DATA'):
        wrappers.append(macro(host, name))
    hs, he = method(host, 'case IDirect3DDevice9Ex_SetTexture:')
    scalar_reader = re.findall(r'PULL_D\(Stage\);\s*PULL_U\(pHandle\);', host[hs:he])
    if len(scalar_reader) != 1:
        raise ValueError('SetTexture: unexpected Host scalar reads')
    wrappers += readers + ['std::array<uint32_t, 2> read_SetTexture() {', scalar_reader[0],
                           'return {Stage, pHandle};', '}', '#undef PULL', '#undef PULL_U',
                           '#undef PULL_D', '#undef PULL_DATA', '#endif']
    metadata['SetTexture'] = {'client_scope_sha256': digest(scope),
                              'host_reader_sha256': digest(scalar_reader[0])}
    (output / 'shader_texture_submissions.h').write_text('\n'.join(wrappers) + '\n', encoding='utf-8')
    transport = output / 'ipc_transport.cpp'
    generated = transport.read_text(encoding='utf-8')
    include = '#include "ipc_transport_cases.cpp"'
    if generated.count(include) != 1:
        raise ValueError('Unexpected transport fixture include')
    transport.write_text(generated.replace(include,
        '#include "shader_texture_submissions.h"\n#include "shader_texture_packets_cases.cpp"'), encoding='utf-8')
    manifest_path = output / 'source-manifest.json'
    manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
    manifest['source_sha256'].update({'client/d3d9_device.cpp': digest(client), 'server/main.cpp': digest(host)})
    manifest['shader_texture_extractions'] = metadata
    manifest['adapters'] += ['exact shader macro and six typed invocation wrappers; API validation/state updates excluded',
                            'exact texture submission scope; uintptr_t stand-in for already resolved COM handle',
                            'original Host scalar/blob PULL macros and statements; D3D9 execution excluded']
    manifest_path.write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=ROOT / '.deps/dxvk-remix')
    parser.add_argument('--output', type=Path, default=ROOT / '.deps/shader-texture-packets')
    args = parser.parse_args()
    generate(args.source.resolve(), args.output.resolve())
